/* Stored ZIP for portable projects. Original Blob objects stay separate from the
   manifest and are never embedded into public HTML or sent to a third party. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ImbaBookBundle=api;})(globalThis,()=>{
 const enc=new TextEncoder(),dec=new TextDecoder('utf-8',{fatal:true});
 const table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
 async function crc(blob){let c=0xffffffff;const reader=blob.stream().getReader();try{for(;;){const {done,value}=await reader.read();if(done)break;for(const b of value)c=table[(c^b)&255]^(c>>>8);}}finally{reader.releaseLock();}return (c^0xffffffff)>>>0;}
 const buffer=n=>new DataView(new ArrayBuffer(n));
 async function pack(manifest,assets,onProgress=()=>{}){
  const entries=[{name:'book.json',blob:new Blob([JSON.stringify(manifest)])},...assets.map(a=>({name:'photos/'+a.id+'.'+({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[a.original.type]||'img'),blob:a.original}))];
  if(entries.length>501)throw Error('В проекте слишком много фотографий.');const chunks=[],central=[];let offset=0;
  for(let i=0;i<entries.length;i++){const {name,blob}=entries[i];if(!/^(book\.json|photos\/[a-zA-Z0-9_-]+\.(jpg|png|webp))$/.test(name))throw Error('Некорректный файл проекта.');if(blob.size>0xffffffff||offset+blob.size>2*1024**3-2*1024**2)throw Error('Проект слишком велик для одного архива.');const nameBytes=enc.encode(name),sum=await crc(blob),h=buffer(30);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint32(14,sum,true);h.setUint32(18,blob.size,true);h.setUint32(22,blob.size,true);h.setUint16(26,nameBytes.length,true);chunks.push(h.buffer,nameBytes,blob);const c=buffer(46);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint32(16,sum,true);c.setUint32(20,blob.size,true);c.setUint32(24,blob.size,true);c.setUint16(28,nameBytes.length,true);c.setUint32(42,offset,true);central.push(c.buffer,nameBytes);offset+=30+nameBytes.length+blob.size;onProgress(i+1,entries.length);}
  const centralSize=central.reduce((s,b)=>s+b.byteLength,0),end=buffer(22);end.setUint32(0,0x06054b50,true);end.setUint16(8,entries.length,true);end.setUint16(10,entries.length,true);end.setUint32(12,centralSize,true);end.setUint32(16,offset,true);return new Blob([...chunks,...central,end.buffer],{type:'application/zip'});
 }
 async function unpack(blob){
  if(blob.size>2*1024**3)throw Error('Архив слишком велик.');const tail=new Uint8Array(await blob.slice(Math.max(0,blob.size-65557)).arrayBuffer());let end=-1;for(let i=tail.length-22;i>=0;i--)if(new DataView(tail.buffer).getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('Не удалось прочитать архив проекта.');const e=new DataView(tail.buffer,tail.byteOffset+end);const count=e.getUint16(10,true),start=e.getUint32(16,true),size=e.getUint32(12,true);if(e.getUint16(4,true)||e.getUint16(6,true)||count>501||start+size>blob.size||size>2*1024**2)throw Error('Неподдерживаемая структура архива.');const c=new DataView(await blob.slice(start,start+size).arrayBuffer()),files=new Map();let pos=0,total=0;
  for(let i=0;i<count;i++){if(pos+46>c.byteLength||c.getUint32(pos,true)!==0x02014b50)throw Error('Повреждён список файлов.');const flags=c.getUint16(pos+8,true),method=c.getUint16(pos+10,true),sum=c.getUint32(pos+16,true),length=c.getUint32(pos+20,true),plain=c.getUint32(pos+24,true),nl=c.getUint16(pos+28,true),xl=c.getUint16(pos+30,true),cl=c.getUint16(pos+32,true),off=c.getUint32(pos+42,true);if(pos+46+nl+xl+cl>c.byteLength||method!==0||flags&1||length!==plain||length>40*1024**2||((c.getUint32(pos+38,true)>>>16)&0xf000)===0xa000)throw Error('Этот архив не создан поддерживаемым конструктором.');const name=dec.decode(new Uint8Array(c.buffer,pos+46,nl));if(!/^(book\.json|photos\/[a-zA-Z0-9_-]{1,100}\.(jpg|png|webp))$/.test(name)||files.has(name))throw Error('Недопустимое имя файла в проекте.');const h=new DataView(await blob.slice(off,off+30).arrayBuffer());if(h.byteLength!==30||h.getUint32(0,true)!==0x04034b50||h.getUint16(8,true)!==0)throw Error('Повреждён файл проекта.');const from=off+30+h.getUint16(26,true)+h.getUint16(28,true);if(from+length>start)throw Error('Границы файла повреждены.');total+=length;if(total>2*1024**3)throw Error('Проект слишком велик.');const type=name.endsWith('.jpg')?'image/jpeg':name.endsWith('.png')?'image/png':name.endsWith('.webp')?'image/webp':'application/json';const file=new Blob([blob.slice(from,from+length)],{type});if(await crc(file)!==sum)throw Error('Файл в архиве повреждён: '+name);files.set(name,file);pos+=46+nl+xl+cl;}
  const manifest=files.get('book.json');if(!manifest||manifest.size>5*1024**2)throw Error('В архиве нет проекта книги.');return {manifest:JSON.parse(await manifest.text()),files};
 }
 return {pack,unpack};
});
